export function t(key, vars) {
  let s = (I18N[S.lang] && I18N[S.lang][key]) || I18N.es[key] || key;
  // split/join, not replace(): a value like "$&" or "$'" (a shop name) must come out exactly as typed.
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.split(`{${k}}`).join(String(v));
  return s;
}
export const locale = () => (S.lang === "en" ? "en-US" : "es-SV");
